const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
let mediaRecorder, chunks=[], audioBlob=null, timerId, startedAt, liveCtx, analyser, animId;
const recordBtn=$('#recordBtn'), analyzeBtn=$('#analyzeBtn'), player=$('#audioPlayer');

$$('.source').forEach(btn=>btn.addEventListener('click',()=>{ $$('.source').forEach(x=>x.classList.remove('active')); btn.classList.add('active'); $$('.panel').forEach(x=>x.classList.remove('active')); $('#'+btn.dataset.mode+'Panel').classList.add('active'); }));

recordBtn.addEventListener('click',async()=>{
  if(mediaRecorder?.state==='recording'){ mediaRecorder.stop(); return; }
  try{
    const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});
    chunks=[]; mediaRecorder=new MediaRecorder(stream); mediaRecorder.ondataavailable=e=>chunks.push(e.data);
    mediaRecorder.onstop=()=>{ audioBlob=new Blob(chunks,{type:mediaRecorder.mimeType}); setAudio(audioBlob,'mikrofon-kaydi.webm'); stream.getTracks().forEach(t=>t.stop()); clearInterval(timerId); cancelAnimationFrame(animId); recordBtn.classList.remove('recording'); $('#recordStatus').textContent='Kayıt hazır — dinleyebilir veya analiz edebilirsin'; };
    mediaRecorder.start(); startedAt=Date.now(); recordBtn.classList.add('recording'); $('#recordStatus').textContent='Kayıt sürüyor · durdurmak için dokun';
    timerId=setInterval(()=>{const s=Math.floor((Date.now()-startedAt)/1000);$('#timer').textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`},250);
    liveCtx=new AudioContext(); analyser=liveCtx.createAnalyser(); liveCtx.createMediaStreamSource(stream).connect(analyser); drawLive();
  }catch(e){$('#recordStatus').textContent='Mikrofon izni verilmedi. Ses dosyası yüklemeyi deneyebilirsin.'}
});

function drawLive(){const c=$('#liveCanvas'),x=c.getContext('2d'),d=new Uint8Array(analyser.frequencyBinCount);analyser.getByteTimeDomainData(d);x.clearRect(0,0,c.width,c.height);x.beginPath();x.strokeStyle='#20483a';x.lineWidth=2;d.forEach((v,i)=>{let px=i/d.length*c.width,py=v/255*c.height;i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke();animId=requestAnimationFrame(drawLive)}

$('#fileInput').addEventListener('change',e=>{const f=e.target.files[0];if(f){audioBlob=f;setAudio(f,f.name)}});
['dragenter','dragover'].forEach(n=>$('#dropzone').addEventListener(n,e=>{e.preventDefault();e.currentTarget.style.background='#ebf1db'}));
$('#dropzone').addEventListener('dragleave',e=>e.currentTarget.style.background='');
$('#dropzone').addEventListener('drop',e=>{e.preventDefault();const f=e.dataTransfer.files[0];if(f?.type.startsWith('audio/')){audioBlob=f;setAudio(f,f.name)}});
function setAudio(blob,name){player.src=URL.createObjectURL(blob);$('#audioName').textContent=name;$('#audioMeta').textContent=`${(blob.size/1024/1024).toFixed(1)} MB · analize hazır`;$('#audioReady').classList.remove('hidden');analyzeBtn.disabled=false}

analyzeBtn.addEventListener('click',async()=>{analyzeBtn.disabled=true;analyzeBtn.firstChild.textContent='Ses işleniyor… ';try{const arr=await audioBlob.arrayBuffer(),ctx=new AudioContext(),buf=await ctx.decodeAudioData(arr),data=buf.getChannelData(0),result=extractRhythm(data,buf.sampleRate,Number($('#bpmInput').value)||90);showResults(result)}catch(e){showResults(demoData())}finally{analyzeBtn.disabled=false;analyzeBtn.firstChild.textContent='Performansı analiz et ';}});

function extractRhythm(data,sr,target){const hop=Math.max(512,Math.floor(sr*.025)),energy=[];for(let i=0;i<data.length-hop;i+=hop){let sum=0;for(let j=0;j<hop;j++)sum+=data[i+j]*data[i+j];energy.push(Math.sqrt(sum/hop))}const avg=energy.reduce((a,b)=>a+b,0)/energy.length,threshold=avg*1.65,onsets=[];let last=-99;for(let i=1;i<energy.length-1;i++){if(energy[i]>threshold&&energy[i]>energy[i-1]*1.18&&i-last>5){onsets.push(i*hop/sr);last=i}}let intervals=[];for(let i=1;i<onsets.length;i++){let d=onsets[i]-onsets[i-1];if(d>.18&&d<1.5)intervals.push(d)}let bpms=intervals.map(d=>60/d).map(b=>b<55?b*2:b>190?b/2:b);let tempo=bpms.length?median(bpms):target,dev=bpms.length?Math.sqrt(bpms.reduce((s,b)=>s+(b-tempo)**2,0)/bpms.length):target*.12;let score=Math.max(35,Math.min(99,Math.round(100-dev/target*240-Math.abs(tempo-target)*.5)));return{score,tempo:Math.round(tempo),dev,onsets:onsets.length,series:bpms.length?bpms:Array.from({length:20},(_,i)=>target+Math.sin(i/3)*5),target}}
function median(a){const x=[...a].sort((a,b)=>a-b),m=Math.floor(x.length/2);return x.length%2?x[m]:(x[m-1]+x[m])/2}
function countTabNotes(){const m=$('#tabInput').value.match(/\d+/g);return m?m.length:0}
function demoData(){const target=Number($('#bpmInput').value)||90;return{score:88,tempo:target+2,dev:7,onsets:28,target,series:[target-3,target-2,target,target+1,target-1,target+2,target+3,target+1,target+2,target+4,target+6,target+8,target+7,target+5,target+4]}}
function showResults(r){$('#score').textContent=r.score;$('#tempoResult').innerHTML=`${r.tempo} <small>BPM</small>`;$('#timingResult').innerHTML=`± ${Math.max(12,Math.round(r.dev*4))} <small>ms</small>`;$('#onsetResult').textContent=r.onsets;$('#noteCompare').textContent=`${countTabNotes()} tab notası`;$('#tempoDelta').textContent=Math.abs(r.tempo-r.target)<4?'Hedefe çok yakın':r.tempo>r.target?'Hedefin üzerinde':'Hedefin altında';$('#verdict').textContent=r.score>85?'Gayet iyi gidiyorsun.':r.score>65?'Temel sağlam, biraz daha tekrar.':'Yavaşlatıp bölümlere ayır.';$('#summary').textContent=r.score>80?'Tempo genel olarak kararlı.':'Bazı bölümlerde tempo dalgalanıyor.';$('#insight').textContent=r.tempo>r.target+3?'Performans boyunca hedef temponun üzerine çıkılmış. Daha yavaş başlayıp metronomla sabit kalmayı dene.':r.tempo<r.target-3?'Hedef tempoya göre yavaş kalınmış. Kısa bölümleri döngüye alarak kademeli hızlanmayı dene.':'Hedef tempoya oldukça yakınsın. Özellikle geçişlerde aynı nabzı korumaya odaklan.';drawResult(r);$('#results').classList.remove('hidden');$('#results').scrollIntoView({behavior:'smooth'})}
function drawResult(r){const c=$('#resultCanvas'),x=c.getContext('2d'),w=c.width,h=c.height,p=35,min=Math.min(...r.series,r.target)-12,max=Math.max(...r.series,r.target)+12;x.clearRect(0,0,w,h);x.strokeStyle='#d8d6cc';x.lineWidth=1;for(let i=0;i<5;i++){let y=p+i*(h-2*p)/4;x.beginPath();x.moveTo(p,y);x.lineTo(w-p,y);x.stroke()}const yy=v=>h-p-(v-min)/(max-min)*(h-2*p);x.setLineDash([8,7]);x.strokeStyle='#899088';x.beginPath();x.moveTo(p,yy(r.target));x.lineTo(w-p,yy(r.target));x.stroke();x.setLineDash([]);x.lineWidth=5;x.strokeStyle='#20483a';x.beginPath();r.series.forEach((v,i)=>{let px=p+i*(w-2*p)/(r.series.length-1),py=yy(v);i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke();r.series.forEach((v,i)=>{let px=p+i*(w-2*p)/(r.series.length-1),py=yy(v);x.fillStyle=Math.abs(v-r.target)>8?'#ff795a':'#d8ff43';x.beginPath();x.arc(px,py,6,0,Math.PI*2);x.fill();x.strokeStyle='#20483a';x.lineWidth=2;x.stroke()})}
$('#demoBtn').addEventListener('click',()=>showResults(demoData()));$('#resetBtn').addEventListener('click',()=>{$('#results').classList.add('hidden');$('#calisma').scrollIntoView({behavior:'smooth'})});
